SELECT e.id_validation,e.workshop_id,v.valid, v.payload || jsonb_build_object('overrideAuthorName', (SELECT string_agg(coalesce(u.steam_name,a.id), ', ' ORDER BY a.n) FROM unnest(s.authors) WITH ORDINALITY a(id,n) LEFT JOIN public."user" u ON u.steam_id::text=a.id)) AS payload FROM zc_private.level_submission_playlist_entry e JOIN zc_private.level_submission_validation v ON v.id=e.id_validation JOIN zc_private.level_submissions s ON s.id=v.id_submission WHERE e.id_playlist=$1 ORDER BY e.position
